{"action": "write", "path": "dedupe.py", "content": "import csv

with open('contacts.csv', newline='') as f:
    rows = list(csv.DictReader(f))

best = {}
for r in rows:
    email = r['email'].strip().lower()
    rec = {'name': r['name'].strip(), 'email': email, 'created': r['created'].strip()}
    # strict '<' keeps the first-appearing row on ties
    if email not in best or rec['created'] < best[email]['created']:
        best[email] = rec

out = sorted(best.values(), key=lambda r: (r['created'], r['email']))

with open('clean.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=['name', 'email', 'created'], lineterminator='\n')
    w.writeheader()
    w.writerows(out)
